- SOURCE_CLAIM_JSON: {"title":"Egypt: Investigate police officers, not detainees, for leaked torture videos","publisher":"Amnesty International","publication_date":"2022-03-14","url":"https://www.amnesty.org/en/latest/news/2022/03/egypt-investigate-police-officers-not-detainees-for-leaked-torture-videos/","claim":"Amnesty says Egyptian authorities responded to leaked prison-abuse videos by investigating detainees and their associates instead of the police officers implicated, and that the videos show detainees with injuries and stress-position abuse.","locator":"Lead paragraphs and video-description section","source_type":"NGO","source_confidence":"high","source_confidence_reason":"Contemporaneous rights investigation with direct review of the videos and follow-on state response.","final_evidence_use":"final_evidence","period_fit":"target-year 2022 police-station abuse episode","ruler_attribution":"Under Sisi's security apparatus and prosecution system; the report concerns state handling, not a private actor.","contrary_evidence":["The Ministry of Interior denied the videos were authentic and claimed the detainees self-harmed."],"lenses":["3B.2","3B.5","3B.6","3B.8","3B.9"]}
- SOURCE_CLAIM_JSON: {"title":"Egypt: Flawed investigation into death in custody missed opportunity for justice","publisher":"Amnesty International","publication_date":"2022-07-07","url":"https://www.amnesty.org/en/latest/news/2022/07/egypt-flawed-investigation-into-death-in-custody-missed-opportunity-for-justice/","claim":"Amnesty and HRW say Egyptian authorities failed to conduct an independent, effective, transparent investigation into economist Ayman Hadhoud's custodial death and ignored evidence of enforced disappearance, torture, and ill-treatment.","locator":"Lead paragraph and body paragraphs on investigation failures","source_type":"NGO","source_confidence":"high","source_confidence_reason":"Joint rights investigation with direct sourcing from official records, witness interviews, and forensic review.","final_evidence_use":"final_evidence","period_fit":"target-year 2022 death-in-custody case","ruler_attribution":"Attributable to state security, prosecution, and detention authorities operating under Sisi.","contrary_evidence":["Officials said the death was non-criminal and attributed it to cardiac causes."],"lenses":["3B.1","3B.2","3B.4","3B.5","3B.10"]}
- SOURCE_CLAIM_JSON: {"title":"Egypt: Detentions, Repression Follow Protest Calls","publisher":"Human Rights Watch","publication_date":"2022-11-16","url":"https://www.hrw.org/news/2022/11/16/egypt-detentions-repression-follow-protest-calls","claim":"Human Rights Watch reported that Egyptian authorities detained hundreds of people nationwide, and that ECRF documented nearly 700 detentions across 18 governorates between October 1 and November 14, 2022, after social-media calls for anti-government protests.","locator":"Lead paragraph and following paragraph","source_type":"NGO","source_confidence":"high","source_confidence_reason":"Contemporaneous independent monitoring with detailed detention counts from a local rights group.","final_evidence_use":"final_evidence","period_fit":"target-year 2022 COP27/protest period","ruler_attribution":"Attributable to the Sisi state and its security services; the arrests were made by Egyptian authorities.","contrary_evidence":["Authorities framed the arrests as lawful security action and rejected the rights groups' account."],"lenses":["3B.5","3B.8","3B.9","3B.10"]}
- SOURCE_CLAIM_JSON: {"title":"Egypt: Arrests over calls for protests during COP27 expose reality of human rights crisis","publisher":"Amnesty International","publication_date":"2022-11-06","url":"https://www.amnesty.org/en/latest/news/2022/11/egypt-arrests-over-calls-for-protests-during-cop27-expose-reality-of-human-rights-crisis/","claim":"Amnesty said Egyptian authorities had arrested hundreds of people in the two weeks before COP27 for alleged support of peaceful protest calls, including at least 151 under Supreme State Security Prosecution investigation.","locator":"Lead paragraphs","source_type":"NGO","source_confidence":"high","source_confidence_reason":"Contemporaneous independent rights reporting with a specific detainee count and legal process details.","final_evidence_use":"final_evidence","period_fit":"target-year 2022 COP27 crackdown","ruler_attribution":"Attributable to Egyptian authorities under Sisi's control.","contrary_evidence":["The government could argue the arrests were preventive security measures."],"lenses":["3B.5","3B.8","3B.9","3B.10"]}
- SOURCE_CLAIM_JSON: {"title":"2022 Country Report on Human Rights Practices: Egypt","publisher":"U.S. Department of State","publication_date":"2023-03-20","url":"https://www.ecoi.net/en/document/2089216.html","claim":"The report lists credible reports of unlawful killings, enforced disappearances, torture, harsh prison conditions, arbitrary detention, political prisoners, restrictions on assembly and association, GBV, and violence targeting LGBTQI+ people, and says the government did not consistently punish abusive officials.","locator":"Executive summary and Section 1 excerpts","source_type":"official","source_confidence":"high","source_confidence_reason":"Primary U.S. government country report summarizing multiple 2022 abuses and enforcement failures.","final_evidence_use":"final_evidence","period_fit":"retrospective report on 2022 conditions","ruler_attribution":"State-level assessment under Sisi's administration, not a direct personal act.","contrary_evidence":["The report also notes some prosecutions of terrorist attacks and some women being appointed to judicial posts."],"lenses":["3B.1","3B.2","3B.4","3B.5","3B.6","3B.7","3B.8","3B.10"]}
- SOURCE_CLAIM_JSON: {"title":"World Report 2023: Egypt","publisher":"Human Rights Watch","publication_date":"2023-01-12","url":"https://www.hrw.org/world-report/2023/country-chapters/egypt","claim":"HRW says that in 2022 Egypt continued forced disappearances, torture, flawed mass-trial practices, arbitrary travel bans and asset freezes, prison abuses, repression around COP27, and re-arrest of some released detainees.","locator":"Lines 68-124 of the chapter","source_type":"NGO","source_confidence":"high","source_confidence_reason":"High-quality annual country chapter synthesizing 2022 reporting across detention, prison, protest, refugees, and gender/sexuality issues.","final_evidence_use":"final_evidence","period_fit":"target-year 2022 synthesis","ruler_attribution":"Attributable to the Sisi government and security institutions; some items are also structural or inherited.","contrary_evidence":["HRW also notes some detainee releases and the national dialogue, but says these did not end the repression campaign."],"lenses":["3B.1","3B.2","3B.4","3B.5","3B.6","3B.8","3B.9","3B.10"]}
- SOURCE_CLAIM_JSON: {"title":"Egypt: Sexually Abused Refugees Find No Justice","publisher":"Human Rights Watch","publication_date":"2022-11-24","url":"https://www.hrw.org/news/2022/11/24/egypt-sexually-abused-refugees-find-no-justice","claim":"HRW documented 11 incidents of sexual violence in Egypt between 2016 and 2022 against refugees and asylum seekers and said police often refused reports or failed to investigate, leaving vulnerable women and girls without protection or justice.","locator":"Lead paragraph and documentation section","source_type":"NGO","source_confidence":"high","source_confidence_reason":"Detailed investigation with victim interviews and documentation of police failure to respond.","final_evidence_use":"final_evidence","period_fit":"target-year 2022 publication with 2016-2022 documented cases","ruler_attribution":"Attributable to Egyptian police and justice authorities under Sisi; the report concerns protection failure, not private crime alone.","contrary_evidence":["The report notes some aid and registration structures exist, but says they did not produce real protection or justice."],"lenses":["3B.2","3B.4","3B.7","3B.10"]}
- SOURCE_CLAIM_JSON: {"title":"Fatal stabbings highlight violence against women in Egypt","publisher":"Reuters via Euronews","publication_date":"2022-08-25","url":"https://www.euronews.com/2022/08/25/egypt-women-violence","claim":"Reuters reported that the murder of Nayera Ashraf and other killings highlighted gaps in legal and social protection for women, and that victims and lawyers said police did not always act when complaints were filed.","locator":"Lead paragraphs and case description sections","source_type":"media","source_confidence":"medium_high","source_confidence_reason":"Independent wire reporting on a concrete 2022 victim case and broader state-protection gap.","final_evidence_use":"final_evidence","period_fit":"target-year 2022 domestic-violence episode","ruler_attribution":"Primarily state protection and policing failure under Sisi, though the immediate killer was a private actor.","contrary_evidence":["The prosecution pursued the killer quickly and the court imposed a death sentence, showing some punitive response after the fact."],"lenses":["3B.7","3B.9","3B.10"]}
- SOURCE_CLAIM_JSON: {"title":"Egypt: Human rights crisis deepens one year after national human rights strategy launched","publisher":"Amnesty International","publication_date":"2022-09-21","url":"https://www.amnesty.org/en/latest/news/2022/09/egypt-human-rights-crisis-deepens-one-year-after-national-human-rights-strategy-launched/","claim":"Amnesty said Egypt showed no genuine will to address its human rights crisis and used the National Human Rights Strategy as a propaganda tool while continuing repression ahead of COP27.","locator":"Lead paragraph and report summary","source_type":"NGO","source_confidence":"high","source_confidence_reason":"Contemporaneous rights analysis tying official reform rhetoric to ongoing repression in 2022.","final_evidence_use":"final_evidence","period_fit":"target-year 2022 policy and repression context","ruler_attribution":"Directly critiques the Sisi administration's human-rights policy and messaging.","contrary_evidence":["The government could argue the strategy and related initiatives signaled reform intent."],"lenses":["3B.4","3B.5","3B.8","3B.10"]}
